package ktanesolver.module.modded.regular.the_crystal_maze;import java.util.*;import org.springframework.stereotype.Service;import ktanesolver.annotation.ModuleInfo;import ktanesolver.dto.ModuleCatalogDto;import ktanesolver.entity.*;import ktanesolver.enums.ModuleType;import ktanesolver.logic.*;
@Service@ModuleInfo(type=ModuleType.THE_CRYSTAL_MAZE,id="crystalMaze",name="The Crystal Maze",category=ModuleCatalogDto.ModuleCategory.MODDED_REGULAR,description="Solve each world’s challenge and track crystals before entering the Dome.",tags={"staged","timer","colors","numbers","minigames"})
public class TheCrystalMazeSolver extends AbstractModuleSolver<TheCrystalMazeInput,TheCrystalMazeOutput>{static final Set<String>COLORS=Set.of("BLUE","BROWN","GREEN","PURPLE","RED","YELLOW");static final int[]LETTERS={7,15,20,5,12,19,9,18,1,16,11,6,23,13,22,4,21,24,3,26,10,25,14,8,17,2};static final Map<String,Integer>RINGS=Map.ofEntries(Map.entry("BLUE/CW",2),Map.entry("BROWN/CW",31),Map.entry("GREEN/CW",5),Map.entry("PURPLE/CW",23),Map.entry("RED/CW",11),Map.entry("YELLOW/CW",17),Map.entry("BLUE/CCW",37),Map.entry("BROWN/CCW",3),Map.entry("GREEN/CCW",29),Map.entry("PURPLE/CCW",7),Map.entry("RED/CCW",19),Map.entry("YELLOW/CCW",13));
	@Override protected SolveResult<TheCrystalMazeOutput>doSolve(RoundEntity round,BombEntity bomb,ModuleEntity module,TheCrystalMazeInput input){if(input==null||input.world()==null)return failure("Choose a Crystal Maze world");Set<String>done=completed(module);if(input.world()==TheCrystalMazeInput.World.RESET){storeState(module,"crystalMazeWorlds",List.of());return success(new TheCrystalMazeOutput("RESET",List.of("Local Crystal Maze progress cleared; enter the regenerated observations."),null,List.of(),0),false);}if(input.world()==TheCrystalMazeInput.World.DOME){if(done.isEmpty())return failure("Win at least one world crystal before entering the Dome");return success(new TheCrystalMazeOutput("DOME",List.of("Enter the Dome","Collect gold tokens only; avoid every silver token","Finish with gold minus silver at 15 or more"),15,List.of(),done.size()));}try{TheCrystalMazeOutput output=switch(input.world()){case AZTEC->aztec(input,done.size());case INDUSTRIAL->industrial(input,done.size());case FUTURISTIC->futuristic(input,done.size());case MEDIEVAL->medieval(input,done.size());default->throw new IllegalStateException();};done.add(input.world().name());storeState(module,"crystalMazeWorlds",List.copyOf(done));return success(new TheCrystalMazeOutput(output.world(),output.actions(),output.answer(),output.targets(),done.size()),false);}catch(IllegalArgumentException exception){return failure(exception.getMessage());}}
	private static TheCrystalMazeOutput fail(String message){throw new IllegalArgumentException(message);}private TheCrystalMazeOutput industrial(TheCrystalMazeInput input,int crystals){String serial=clean(input.industrialSerial());if(!serial.matches("[A-Z]{5}"))return fail("Industrial machine serial must contain five letters");int x=value(serial.charAt(0))+value(serial.charAt(4)),y=value(serial.charAt(1))+value(serial.charAt(3)),z=Math.floorMod(x*y,value(serial.charAt(2)));return new TheCrystalMazeOutput("INDUSTRIAL",List.of("Set the display to "+z,"Press REVERSE"),z,List.of(),crystals);}private static int value(char letter){return LETTERS[letter-'A'];}
	private TheCrystalMazeOutput medieval(TheCrystalMazeInput input,int crystals){if(input.medievalRings()==null||input.medievalRings().size()!=4)return fail("Enter all four rings from outside to inside");int sum=0;for(String raw:input.medievalRings()){String ring=clean(raw).replace(':','/').replace("COUNTERCLOCKWISE","CCW").replace("COUNTER-CLOCKWISE","CCW").replace("CLOCKWISE","CW");Integer value=RINGS.get(ring);if(value==null)return fail("Each ring must be COLOR/CW or COLOR/CCW");sum+=value;}int digit=sum%10;return new TheCrystalMazeOutput("MEDIEVAL",List.of("Press the target when the game timer ends in "+digit),digit,List.of(),crystals);}
	private TheCrystalMazeOutput futuristic(TheCrystalMazeInput input,int crystals){if(input.futuristicScreens()==null||input.futuristicScreens().size()!=3)return fail("Enter the three cycles, one per screen");List<String>targets=new ArrayList<>();for(int screen=0;screen<3;screen++){String[]pairs=clean(input.futuristicScreens().get(screen)).split("[,\\s]+");if(pairs.length!=3)return fail("Each Futuristic screen needs three WORD/COLOR pairs");boolean[]matches=new boolean[3];String[]normalized=new String[3];for(int i=0;i<3;i++){String[]parts=pairs[i].replace(':','/').split("/");if(parts.length!=2||!COLORS.contains(parts[0])||!COLORS.contains(parts[1]))return fail("Futuristic pairs must use WORD/COLOR with the six manual colors");matches[i]=parts[0].equals(parts[1]);normalized[i]=parts[0]+"/"+parts[1];}int count=0;for(boolean match:matches)if(match)count++;if(count==0||count==3)return fail("Each screen must have one matching anomaly or one differing anomaly");boolean anomaly=count==1;int index=0;while(matches[index]!=anomaly)index++;targets.add("SCREEN "+(screen+1)+": "+normalized[index]);}return new TheCrystalMazeOutput("FUTURISTIC",targets,null,List.copyOf(targets),crystals);}
	private TheCrystalMazeOutput aztec(TheCrystalMazeInput input,int crystals){if(input.aztecTargetWeight()==null||input.aztecSwitchInterval()==null||input.aztecCurrentWeight()==null||input.aztecClicks()==null||input.aztecButtonValues()==null||input.aztecButtonValues().size()!=2)return fail("Enter the Aztec target and current post-swap state");int target=input.aztecTargetWeight(),interval=input.aztecSwitchInterval(),weight=input.aztecCurrentWeight(),clicks=input.aztecClicks(),left=input.aztecButtonValues().get(0)==null?0:input.aztecButtonValues().get(0),right=input.aztecButtonValues().get(1)==null?0:input.aztecButtonValues().get(1);if(target<125||target>175||interval<15||interval>20||weight<0||weight>target||clicks<0||!((left==1&&right==2)||(left==2&&right==1)))return fail("Aztec values are outside the source-generated ranges");List<String>presses=aztecPath(target,interval,weight,clicks,left);if(presses==null)return fail("No exact Aztec weight path exists from this state");List<String>actions=new ArrayList<>(presses);actions.add("ADD");return new TheCrystalMazeOutput("AZTEC",List.copyOf(actions),target,List.of(),crystals);}
	static List<String>aztecPath(int target,int interval,int startWeight,int clicks,int leftValue){record State(int weight,int clickMod,int left){}record Step(State previous,String action){}State start=new State(startWeight,Math.floorMod(clicks,interval),leftValue);Map<State,Step>seen=new LinkedHashMap<>();ArrayDeque<State>queue=new ArrayDeque<>();seen.put(start,null);queue.add(start);State end=null;while(!queue.isEmpty()){State state=queue.remove();if(state.weight==target){end=state;break;}for(String action:List.of("LEFT","RIGHT")){int added=action.equals("LEFT")?state.left:3-state.left,newWeight=state.weight+added;if(newWeight>target)continue;int mod=(state.clickMod+1)%interval,newLeft=mod==0?3-state.left:state.left;State next=new State(newWeight,mod,newLeft);if(!seen.containsKey(next)){seen.put(next,new Step(state,action));queue.add(next);}}}if(end==null)return null;LinkedList<String>path=new LinkedList<>();while(!end.equals(start)){Step step=seen.get(end);path.addFirst(step.action);end=step.previous;}return List.copyOf(path);}
	private static Set<String>completed(ModuleEntity module){Set<String>done=new LinkedHashSet<>();if(module.getState().get("crystalMazeWorlds")instanceof Collection<?>values)values.forEach(value->done.add(String.valueOf(value)));return done;}private static String clean(String value){return value==null?"":value.trim().toUpperCase(Locale.ROOT).replaceAll("\\s*/\\s*","/");}}
